DROP POLICY IF EXISTS "Employees can sign their own contract" ON public.employment_contracts; CREATE POLICY "Employees can sign their own contract" ON public.employment_contracts FOR UPDATE TO authenticated USING (employee_id = (SELECT p.id FROM public.profiles p WHERE p.user_id = auth.uid())) WITH CHECK ( employee_id = (SELECT p.id FROM public.profiles p WHERE p.user_id = auth.uid()) AND NOT (id IS DISTINCT FROM (SELECT c.id FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (company_id IS DISTINCT FROM (SELECT c.company_id FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (employee_id IS DISTINCT FROM (SELECT c.employee_id FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (contract_type IS DISTINCT FROM (SELECT c.contract_type FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (contract_file_path IS DISTINCT FROM (SELECT c.contract_file_path FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT ("position" IS DISTINCT FROM (SELECT c."position" FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (employment_percentage IS DISTINCT FROM (SELECT c.employment_percentage FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (start_date IS DISTINCT FROM (SELECT c.start_date FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (end_date IS DISTINCT FROM (SELECT c.end_date FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (probation_period_months IS DISTINCT FROM (SELECT c.probation_period_months FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (signed_by_employer IS DISTINCT FROM (SELECT c.signed_by_employer FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (notes IS DISTINCT FROM (SELECT c.notes FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (created_at IS DISTINCT FROM (SELECT c.created_at FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (employer_signature IS DISTINCT FROM (SELECT c.employer_signature FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (work_description IS DISTINCT FROM (SELECT c.work_description FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (workplace_address IS DISTINCT FROM (SELECT c.workplace_address FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (has_multiple_workplaces IS DISTINCT FROM (SELECT c.has_multiple_workplaces FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (remote_work_allowed IS DISTINCT FROM (SELECT c.remote_work_allowed FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (remote_work_details IS DISTINCT FROM (SELECT c.remote_work_details FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (working_hours_per_week IS DISTINCT FROM (SELECT c.working_hours_per_week FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (working_hours_per_day IS DISTINCT FROM (SELECT c.working_hours_per_day FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (work_time_arrangement IS DISTINCT FROM (SELECT c.work_time_arrangement FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (break_duration_minutes IS DISTINCT FROM (SELECT c.break_duration_minutes FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (variable_working_hours IS DISTINCT FROM (SELECT c.variable_working_hours FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (variable_hours_description IS DISTINCT FROM (SELECT c.variable_hours_description FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (shift_change_rules IS DISTINCT FROM (SELECT c.shift_change_rules FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (temporary_reason IS DISTINCT FROM (SELECT c.temporary_reason FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (vacation_days IS DISTINCT FROM (SELECT c.vacation_days FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (holiday_pay_percentage IS DISTINCT FROM (SELECT c.holiday_pay_percentage FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (vacation_rules IS DISTINCT FROM (SELECT c.vacation_rules FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (salary_amount IS DISTINCT FROM (SELECT c.salary_amount FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (salary_type IS DISTINCT FROM (SELECT c.salary_type FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (payment_method IS DISTINCT FROM (SELECT c.payment_method FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (payment_day IS DISTINCT FROM (SELECT c.payment_day FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (overtime_compensation IS DISTINCT FROM (SELECT c.overtime_compensation FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (other_allowances IS DISTINCT FROM (SELECT c.other_allowances FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (notice_period_employee_months IS DISTINCT FROM (SELECT c.notice_period_employee_months FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (notice_period_employer_months IS DISTINCT FROM (SELECT c.notice_period_employer_months FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (termination_procedures IS DISTINCT FROM (SELECT c.termination_procedures FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (is_staffing_agency IS DISTINCT FROM (SELECT c.is_staffing_agency FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (client_company_name IS DISTINCT FROM (SELECT c.client_company_name FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (client_company_org_number IS DISTINCT FROM (SELECT c.client_company_org_number FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (training_provisions IS DISTINCT FROM (SELECT c.training_provisions FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (pension_scheme IS DISTINCT FROM (SELECT c.pension_scheme FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (insurance_provisions IS DISTINCT FROM (SELECT c.insurance_provisions FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (sick_pay_rules IS DISTINCT FROM (SELECT c.sick_pay_rules FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (has_collective_agreement IS DISTINCT FROM (SELECT c.has_collective_agreement FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (collective_agreement_name IS DISTINCT FROM (SELECT c.collective_agreement_name FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (collective_agreement_parties IS DISTINCT FROM (SELECT c.collective_agreement_parties FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (special_work_time_exemptions IS DISTINCT FROM (SELECT c.special_work_time_exemptions FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) AND NOT (special_work_time_details IS DISTINCT FROM (SELECT c.special_work_time_details FROM public.employment_contracts c WHERE c.id = employment_contracts.id)) );

REVOKE SELECT ON public.profiles FROM authenticated;
REVOKE SELECT ON public.profiles FROM anon;
GRANT SELECT (id, user_id, company_id, first_name, last_name, email, phone, avatar_url, is_active, created_at, updated_at, hms_card_required, hms_card_obtained, hms_card_expiry_date, hms_card_reminder_sent_30_days, hms_card_reminder_sent_7_days, hms_card_reminder_sent_90_days, hms_card_reminder_sent_60_days, is_verneombud, is_hms_responsible, primary_department_id, status, is_assigned_to_main, preferred_language, deleted_at) ON public.profiles TO authenticated;
